// ============================================================
//  Q006 Hormone Checklist (Women) — Normalize Input & Score
//  Replicates the Make.com "Array of Scores" + "Determine Result"
//  modules exactly.
//
//  The Make scenario relied on Typeform's built-in scoring: each
//  selected symptom adds a weight so the TOTAL score is a packed
//  number encoding 4 category counts, 2 digits each:
//      [cat4][cat3][cat2][cat1]  (last 8 digits, left-padded)
//  e.g. score 2030401 -> 02 03 04 01 -> cat4=2 cat3=3 cat2=4 cat1=1
//
//  This node accepts ANY of these input shapes (checked in order):
//   1) Native Typeform webhook payload  -> form_response.calculated.score
//   2) Flat body with packed "score" (or "S") already computed
//   3) Flat body with cat1..cat4 sent directly by the frontend
//   4) Flat body with raw symptom arrays -> mapped via SYMPTOM_CATEGORY
// ============================================================

// ---- CONFIG -------------------------------------------------
// Only needed for input shape (4). Assign each symptom label to
// its category (1-4) exactly as configured in Typeform's scoring
// settings. Unmapped symptoms are ignored (with a warning).
const SYMPTOM_CATEGORY = {
  // --- Q2: Psychological symptoms (fill category numbers) ---
  'mood swings (pms)': 0,
  'foggy thinking': 0,
  'depressed mood': 0,
  'irritability': 0,
  'low libido / decreased sexual function': 0,
  'food cravings': 0,
  'sugar cravings': 0,
  'sleep disturbances': 0,
  'anxiety': 0,
  'feeling cold all the time': 0
  // --- Q1: Physical symptoms (add labels + categories) ---
};
// -------------------------------------------------------------

const root = $input.first().json;
const body = root.body || root;
const warnings = [];

let email = '', firstName = '', mailingList = '';
let packedScore = null;
let cat1 = null, cat2 = null, cat3 = null, cat4 = null;

// ---- Shape 1: native Typeform webhook ----------------------
const fr = body.form_response || root.form_response;
if (fr) {
  packedScore = fr.calculated && fr.calculated.score != null ? Number(fr.calculated.score) : 0;
  const answers = fr.answers || [];
  // Field IDs taken from the live Make.com scenario
  const FID_EMAIL   = 'b9cd05da-43bc-4d3f-a5ff-273faf34e5ca';
  const FID_NAME    = 'ea587d94-78e8-4808-876f-ab8b33debdd3';
  const FID_OPTIN   = '6673c18d-a07c-4bfc-a47d-e4bfb3cdabdb';
  for (const a of answers) {
    const fid = a.field && (a.field.id || a.field.ref);
    if (fid === FID_EMAIL || a.type === 'email') email = a.email || email;
    if (fid === FID_NAME) firstName = a.text || firstName;
    if (fid === FID_OPTIN && a.choice) mailingList = a.choice.label || mailingList;
  }
  // Fallbacks by type if IDs ever change
  if (!firstName) {
    const t = answers.find(a => a.type === 'text');
    if (t) firstName = t.text || '';
  }
  if (!mailingList) {
    const c = answers.find(a => a.type === 'choice');
    if (c && c.choice) mailingList = c.choice.label || '';
  }
} else {
  // ---- Flat body (custom Typeform-style HTML frontend) ------
  email       = body.email || body.patientEmail || '';
  firstName   = body.first_name || body.firstName || body.name || '';
  mailingList = body.mailing_list || body.mailingList || body.newsletter || '';

  if (body.score != null || body.S != null) {
    // Shape 2: packed score sent by frontend
    packedScore = Number(body.score != null ? body.score : body.S);
  } else if (body.cat1 != null || body.cat2 != null || body.cat3 != null || body.cat4 != null) {
    // Shape 3: category scores sent directly
    cat1 = Number(body.cat1 || 0);
    cat2 = Number(body.cat2 || 0);
    cat3 = Number(body.cat3 || 0);
    cat4 = Number(body.cat4 || 0);
  } else {
    // Shape 4: raw symptom selections
    const collect = (v) => Array.isArray(v) ? v : (typeof v === 'string' && v ? v.split(',') : []);
    const selected = [
      ...collect(body.psychological_symptoms || body.psych_symptoms || body.q1),
      ...collect(body.physical_symptoms || body.q2)
    ];
    const counts = { 1: 0, 2: 0, 3: 0, 4: 0 };
    for (const s of selected) {
      const key = String(s).trim().toLowerCase();
      const c = SYMPTOM_CATEGORY[key];
      if (c >= 1 && c <= 4) counts[c]++;
      else warnings.push('Unmapped symptom: ' + key);
    }
    cat1 = counts[1]; cat2 = counts[2]; cat3 = counts[3]; cat4 = counts[4];
  }
}

// ---- Decode packed score (identical to Make substring logic) ----
if (cat1 === null) {
  const s = String(Math.trunc(Number(packedScore) || 0));
  const padded = ('00000000' + s).slice(-8);
  cat1 = parseInt(padded.slice(6, 8), 10); // last 2 digits
  cat2 = parseInt(padded.slice(4, 6), 10);
  cat3 = parseInt(padded.slice(2, 4), 10);
  cat4 = parseInt(padded.slice(0, 2), 10); // first 2 of the last 8
} else {
  packedScore = cat4 * 1000000 + cat3 * 10000 + cat2 * 100 + cat1;
}

// ---- Determine result (verbatim Make.com logic) ----------------
// if all 4 categories > 0            -> 5
// else if cat1+cat2 > cat3+cat4      -> (cat1 > cat2 ? 1 : 2)
// else                               -> (cat3 > cat4 ? 3 : 4)
let result;
if (cat1 > 0 && cat2 > 0 && cat3 > 0 && cat4 > 0) {
  result = 5;
} else if (cat1 + cat2 > cat3 + cat4) {
  result = cat1 > cat2 ? 1 : 2;
} else {
  result = cat3 > cat4 ? 3 : 4;
}

// Q006 landing page — value of "Landing Page URL" in the Make Data Store record "Q006"
const REDIRECT_BASE_URL = 'https://hrt.org/checklist/hormone-symptom-checklist-for-women-female-hormone-imbalance-test';
const redirectUrl = REDIRECT_BASE_URL
  + '?cat1=' + cat1 + '&cat2=' + cat2 + '&cat3=' + cat3 + '&cat4=' + cat4;

return [{ json: {
  patientName:  String(firstName || '').trim(),
  patientEmail: String(email || '').trim(),
  mailingList:  String(mailingList || '').trim(),
  packedScore,
  cat1, cat2, cat3, cat4,
  result,
  redirectUrl,
  _debug_warnings: warnings
}}];

