let L;
function _Lbase(key, col) {
  const e = CONTENT[key];
  if (!e) return '';
  if (typeof e === 'string') return e;
  if (col === 2) return e.text || '';
  if (col === 4) return e.title || '';
  if (col === 5) return e.description || '';
  if (col === 6) return e.link || '';
  if (col === 7) return key.indexOf('RC') === 0 ? (e.image || '') : (e.subtitle || '');
  if (col === 8) return e.image || '';
  return '';
}

// Treat leftover skeleton strings as empty so nothing leaks to a patient.
const _isPlaceholder = (v) => {
  const s = String(v == null ? '' : v).trim();
  if (s === '') return true;
  if (/^(TITLE|SUBTITLE|DESCRIPTION)$/i.test(s)) return true;
  if (/^PASTE\b/i.test(s)) return true;
  if (/PASTE-|REPLACE-|\/IMAGE$|^https:\/\/IMAGE$/i.test(s)) return true;
  if (s === 'https://' || s === 'http://') return true;
  return false;
};
const _Lraw = _Lbase;
L = function (key, col) {
  const v = _Lraw(key, col);
  return _isPlaceholder(v) ? '' : v;
};
// Q006's Make template keeps the newline AND adds <br/>
function nl2br(s) { return String(s || '').replace(/\r\n|\r|\n/g, '\n<br/>'); }
// startcase equivalent (Make's startcase title-cases each word)
function startCase(s) {
  return String(s || '').toLowerCase().replace(/(^|\s|-)\S/g, c => c.toUpperCase());
}

const d = $input.first().json;
// Escape only the dynamic name used in the HTML greeting.
function escapePatientName(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
const greeting = d.patientName ? ('Dear\u00a0' + escapePatientName(startCase(d.patientName))) : 'Hi\u00a0there';
const result = d.result;
const cat1 = d.cat1, cat2 = d.cat2, cat3 = d.cat3, cat4 = d.cat4;
const year = new Date().getFullYear();


// ---- Fail-safe pass: drop tiles with no real content, blank broken images ----
const TRANSPARENT_PX = 'data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==';
function _dropEmptyTiles(markup) {
  let out = markup;
  // product / lab-test tiles
  out = out.replace(/<tr>\s*<td bgcolor="#FFFFFF" class="t_shadow_block">[\s\S]*?<\/a>\s*<\/td>\s*<\/tr>/g,
    (block) => { const m = block.match(/<img alt="([^"]*)"/); return (m && m[1].trim()) ? block : ''; });
  // blog / related-content cards
  out = out.replace(/<t[hd] bgcolor="#FFFFFF"[^>]*class="force-col-th"[^>]*>[\s\S]*?<\/a>\s*<\/t[hd]>/g,
    (block) => { const m = block.match(/<img alt="([^"]*)"/); return (m && m[1].trim()) ? block : ''; });
  // drop whole sections whose tiles were all removed (no tile anchor left)
  out = out.replace(/<!--SEC:[A-Z]+-->[\s\S]*?<!--\/SEC:[A-Z]+-->/g,
    (sec) => sec.includes('class="a_block"') ? sec : '');
  // strip the section markers themselves
  out = out.replace(/<!--\/?SEC:[A-Z]+-->/g, '');
  // collapse blank intro / result gaps (empty text leaves runs of <br/>)
  out = out.replace(/(?:\s*<br\/>\s*){3,}/g, '<br/><br/>\n');
  // any surviving empty image src -> transparent pixel (no broken-image icon)
  out = out.replace(/src=""/g, 'src="' + TRANSPARENT_PX + '"');
  return out;
}

const emailSubject = L('TITLE', 2) + ' - Results | HRT.org';
const landingPageUrl = L('LP' + result, 2)
  + '?cat1=' + cat1 + '&cat2=' + cat2 + '&cat3=' + cat3 + '&cat4=' + cat4;

